# Prepare the FRIENDS_2 screening data (friends/data/full_screening_w_humans_FRIENDS_2.rds) for the
# priority-screening simulation, mirroring the role data_manipulation.r plays for the original dataset.
library(dplyr)
library(AIscreenR)
library(CiteSource)
library(stringr)

raw <- readRDS("friends/data/full_screening_w_humans_FRIENDS_2.rds")

# `answer_data` carries a stray `title`/`title.y` (NA except for finally-included rows) and
# `finally_included` from an earlier join attempt; `title.x` is the real title/abstract-stage title.
friends_data <- raw$answer_data |>
  select(-any_of(c("title", "title.y", "finally_included"))) |>
  rename(title = title.x, human_code = final_human_decision)

# Final-included studies list (post Barrett-2006 removal, see friends_final_included.ris).
final_inc <- AIscreenR::read_ris_to_dataframe("friends_final_included.ris")

final_inc_matched <- final_inc |>
  select(eppi_id, title_fd = title, abstract_fd = abstract) |>
  left_join(
    friends_data |> select(eppi_id, decision_binary, human_code, title, abstract),
    by = "eppi_id"
  ) |>
  mutate(
    title    = coalesce(title, title_fd),
    abstract = coalesce(abstract, abstract_fd)
  ) |>
  select(-title_fd, -abstract_fd)

# Artificially add any finally included studies that were not screened by AI (decision_binary = NA)
# and assign them decision_binary = 1 and human_code = 1, so they are treated as relevant records
# in the priority screening process.
studies_missing_from_friends_data <- final_inc_matched |>
  filter(is.na(decision_binary)) |>
  mutate(decision_binary = 1, human_code = 1)

friends_data <- friends_data |>
  bind_rows(studies_missing_from_friends_data |> filter(!eppi_id %in% friends_data$eppi_id)) |>
  mutate(
    included_final  = as.integer(eppi_id %in% final_inc$eppi_id),
    human_and_ai_in = as.integer(decision_binary == 1L & human_code == 1L)
  )

# Deduplicate the dataset to ensure unique records (by eppi_id).
friends_data <- CiteSource::dedup_citations(friends_data) |>
  # Drop "duplicate_id"
  select(-duplicate_id)

# Make data frame withstudies from friends_data that have "No information" in friends_data$abstract and 1 in human_code
empty_abstracts <- friends_data |>
  filter(abstract == "No information" & human_code == 1L)

# Print empty_abstracts$author_short along with the corresponding title
print_empty_abstracts <- empty_abstracts |>
  select(author_short, title, eppi_id)
print(print_empty_abstracts, n = nrow(print_empty_abstracts))

# Abstracts found online for studies missing them, keyed by eppi_id (looked up from the titles
# above so the match doesn't depend on title text or row order). A handful of studies
# (NCT01802424, Beccaria, Haidari, Dohl, Ghajareih, Sykes, and the second Kösters study) had no
# abstract available online and are left as "No information".
found_abstracts <- tibble::tribble(
  ~eppi_id, ~abstract_text,

  "91152964", # Ghaderi (2013) - School-based Universal Prevention for Anxiety and Depression in Sweden...
  "Our study aimed at evaluating FRIENDS for Life, an intervention to prevent anxiety and depression in Swedish school children. A total of 695 children between the ages of 8 and 11 were recruited from 17 schools in Stockholm, Sweden, and cluster-randomized to either the intervention or control group. Teachers in the intervention group received a full day of training and administered FRIENDS for Life in their classrooms. We assessed the children's anxiety and depressive symptoms, general mental health, and academic performance at pre- and post-intervention as well as at the 12-month follow-up. A multi-informant approach was used with data collected from children, parents, and teachers. Assessment was done with the Spence Children's Anxiety Scale, Children's Depression Inventory, and the Strengths and Difficulties Questionnaire. Children's baseline symptoms, gender, and age as well as their teacher's use of supervision were examined as moderators of effect. Our study found no short- or long-term effects of the intervention for any outcome with regard to the entire sample. We found an enhanced effect of the intervention regarding children with elevated depressive symptoms at baseline. We found a decrease in anxiety symptoms among children whose teachers attended a larger number of supervision sessions, compared to children whose teachers attended fewer supervised sessions or the control group. Mediation analyses showed that this effect was driven by change in the last phase of the intervention, suggesting that supervision might play an important role in enhancing teachers' ability to administer the intervention effectively.",

  "91152984", # Pahl (2010) - Preventing anxiety and promoting social and emotional strength in preschool children...
  "This study sought to examine, for the first time, the efficacy of The Fun FRIENDS program (Barrett, 2007a, b), a school-based, universal preventative intervention program for preschool children. The Fun FRIENDS program aims to teach children cognitive-behavioural strategies in a play-based manner to prevent anxiety and to increase social and emotional strength. Participants were 263 children aged four to six years attending preschool in Brisbane, Australia. Schools were randomly allocated to an intervention group (IG) or a waiting list control group (WLG). Parent report data revealed no significant differences between the IG and WLG on anxiety, behavioural inhibition (BI) and social-emotional strength at post-intervention. At 12-month follow-up, improvements were found on anxiety, BI and social-emotional competence for children in the IG. Teacher reports revealed significant improvements at post-intervention on BI and social-emotional strength for children who had received the program. The implications of these findings are discussed, along with limitations and directions for future research.",

  "91152985", # Barrett (2001) - Examining the social validity of the FRIENDS treatment program for anxious children
  "This study conducted the first evaluation of elements of social validity of the FRIENDS program, a cognitive-behavioural treatment package for childhood anxiety disorders. Parents, children, and adolescents were surveyed over time on their global satisfaction with the program, the acceptability of treatment components, and the completion of homework tasks. Results indicated a high level of satisfaction with the FRIENDS program and a high completion rate of homework tasks. Contrary to expectations, children rated the cognitive skills as more useful than adolescents did. Adolescents reported the behavioural strategy of graded exposure as more useful than other strategies. In addition, the relationship between treatment acceptability and clinical outcome was not significant. Limitations of the study and directions for further research are discussed.",

  "91578469", # Paul - Evaluating the impact of a universal FRIENDS for Life Programme...
  "FRIENDS For Life' (Barrett, 2004) is a ten-week programme for children aged 7 - 11 years, based on cognitive behavioural principles, designed to teach coping skills and techniques to manage anxiety and depression. This study describes an evaluation of a universal programme, delivered to a class of Year 5 children in a school in a socio-economically disadvantaged community located in the East of England.\n\nA review of literature, combining narrative and systematic approaches, presents what is known about the development of emotional distress and academic self-perceptions in children, underpinned by the principles of Social Cognitive Theory (Bandura, 1986). Evidence for the effectiveness of Cognitive Behavioural Therapy with children is critiqued, with specific attention to the FRIENDS programme delivered as a universal intervention.\n\nA quasi-experimental non-equivalent groups design (intervention group and wait-list control) was employed to evaluate the impact of the programme upon children's levels of emotional distress, their academic self-perceptions and teacher ratings of pupil behaviour. Pre and post-test measures comprised the Paediatric Index of Emotional Distress, (O'Connor et al, 2010), the Myself-As-Learner Scale (Burden, 1998) and the Strengths and Difficulties Questionnaire (Goodman, 1997).\n\nA change score analysis revealed statistically significant reductions in self-reported levels of emotional distress and teacher-rated hyperactivity for the intervention group in comparison to the control group. Both groups showed significantly improved overall behaviour and prosocial skills. There was no evidence of a significant change between or within groups for academic self-perceptions. The limitations associated with quasi-experimental designs are highlighted, together with the difficulties of operationalising abstract constructs such as 'emotional distress' and 'academic self-concept.'\n\nThe results are discussed in relation to the theoretical and methodological implications highlighted in previous chapters. Particular attention is paid to the significance of contextual influences operating in concert with the programme components in mediating outcomes. Implications for future research and the role of the Educational Psychologist supporting universal therapeutic programmes in schools are discussed.",

  "91578489", # DeSousa - Community Trial of the FRIENDS for Life Prevention Program...
  "The aim of this study was to investigate the effectiveness of the FRIENDS for Life program in the selective prevention format with children at risk for internalizing disorders living in countryside areas. The study also examined the association between response to treatment and a series of individual variables. Participants were 111 children aged 7 to 12 years old (M = 9.33; SD = 1.58), 55% boys. The intervention was delivered in 10 sessions by trained teachers supervised by a clinical psychologist, in groups of six to twelve children each. There was a significance reduction in anxiety and depressive symptoms after the intervention, with a small effect size. The only predictor that demonstrated significant association with response to treatment was the severity of pre-treatment anxiety. Our results support the effectiveness of the FRIENDS for Life program in the prevention format in a new culture and a non-privileged context.",

  "91578504", # García - Evaluation of the Eff ectiveness of the Fun FRIENDS Program
  "Anxiety and depression are the main complaints related to mental health in childhood and constitute a public health problem. In Brazil, there are few studies that describe evidence-based early intervention actions for these psychopathologies. Considering the problems related to anxiety and depression in childhood and their relative stability in development, health promotion and prevention actions are justified. One of the evidence-based programs directed toward health promotion and prevention of anxiety and depression in childhood is the FRIENDS Program (Fun FRIENDS). Therefore, this study sought to evaluate the effectiveness of the FRIENDS program regarding the reduction in symptoms of anxiety and depression and increase in socioemotional skills, in a city of Paraná state. A total of 25 children, aged from 5 to 7, and their caregivers participated. The CBCL (Child Behavior Checklist), SDQ (Strengths and Difficulties Questionnaire) and SCAS (Spence Children's Anesthesia Scale) were used as the evaluation instruments. The results demonstrated increases in socioemotional skills and reductions in anxiety and depression symptoms. Thus, it was concluded that there is evidence that supports the effectiveness of the program for the Brazilian population.",

  "91578511", # Mostert - PILOT STUDY OF THE EFFECTIVENESS OF THE FRIENDS- PROGRAMME IN A SOUTH AFRICAN SAMPLE
  "Anxiety symptoms seem highly prevalent amongst South African children, as recent studies indicate. Even though early intervention and prevention is advocated, an effective prevention- and early intervention programme for childhood anxiety is lacking for the South African context. Therefore, the present study was motivated from the need for an effective anxiety prevention- and early intervention programme for use with South African children. Thus the primary aim of the present study was to determine whether the Australian FRIENDS programme could effectively reduce the anxiety symptoms in a sample of South African children. In addition, literature also suggests self-efficacy to have a unique contribution in the etiology of anxiety. The question has also been raised in literature whether the effectiveness of childhood anxiety interventions cannot be ascribed to the enhancement of self-efficacy for dealing with feared stimuli. Thus, as a sub-aim the study explored whether the FRIENDS programme could effectively enhance the self-efficacy of the sample. Hence, for the present pilot study, a programme evaluation was conducted into the effectiveness of the FRIENDS programme, a prevention- and early intervention programme for childhood anxiety. A quasi-experimental design, in the form of a non-equivalent wait-list comparison group design, was used in the present study. Thus, there were two conditions to the study: an intervention condition and a wait-list control condition. On ethical grounds, both the intervention group and the wait-list control group received the intervention during the course of the study. An ad hoc sample was drawn from an accessible population of 12-year-old children. This resulted in 66 children (30 girls, 36 boys) from a formerly disadvantaged neighbourhood in the Stellenbosch area participating in the study. The study followed participants over a course of 10 months during which participants' anxiety symptoms and self-efficacy were assessed at four occasions. The intervention programme, the 'FRIENDS' programme that is a 10-session Cognitive Behaviour Therapy prevention- and early intervention programme for childhood anxiety, was conducted firstly with the intervention group and lastly with the wait-list control group. To assess participants' anxiety symptoms, two self-report anxiety questionnaires, the Spence Children's Anxiety Scale (SCAS) and the Revised Children's Manifest Anxiety Scale (RCMAS) were used. Participants' self-efficacy was assessed with a self-report questionnaire, the Self-Efficacy Questionnaire for Children (SEQ-C). The data of 46 participants were used in the analysis of the data that explored both between group effects and within group effects. The between group effects were analysed using one-way ANOVA's, and within group effects were analyzed using repeated measures ANOVA's. Regarding the between group effects, results indicated no significant difference between the intervention group and the wait-list control group on either the measures of anxiety or the measure of self-efficacy at any four times of assessment. Regarding the within group effects, results indicated a significant effect for time for the intervention group on the SCAS data, however the same effect was not found for the wait-list control group. Also, no significant within group effects were found for either group on the RCMAS data or the SEQ-C data. The implications of these findings, with regard to the effectiveness of the FRIENDS programme, are discussed in addition to a discussion of the limitations of the present study and the recommendations for further research.",

  "91578515", # Syros (2020) - Innovative Strategies and Challenges for the Prevention of Pathological Anxiety...
  "The effects of pathological anxiety on public health have led to the realization that anxious children might experience significant limitations in their lives. Evidence-based cognitive-behavioral (CB) interventions are now being implemented in schools at a group level to combat anxiety. Childhood emotional health should be considered a national and global priority for an effective strategy promoting the prevention of mental health. The aim of this study is the description of novel data on the effectiveness of preventive interventions for anxious children, as well as the study of selective parameters that appear to affect treatment outcome. Furthermore, a brief review is cited regarding two empirically supported interventions, which include the Friends and Pyramid Club program and the Super Skills for Life program. Schools are considered suitable places for all types of prevention programs; they provide a familiar environment to a child, and by providing access to the prevention programs to many children, school programs could be the ideal way for anxious young individuals to practice and generalize their skills. Schools also offer an ideal space for collaboration between teachers and mental health professionals. Most programs have been effective in reducing anxiety, especially those based on the principles of CB, where the effects appear to be independent of the professional status of the leader (trained teacher or mental health professional). Friends and Pyramid Club interventions are well-established, multifaceted, and cost-effective programs, which include combinations of techniques (mostly behavioral activation, cognitive preparation, teaching social skills, and relaxation techniques). Super Skills for Life is a promising program, which also uses video feedback as a part of treatment. Prevention programs have been established as a vital part of the treatment options for specialists. Research related to childhood anxiety is increasing, while the perspectives for finding novel data seem promising for the upcoming years. In this context, several studies reveal the need for early, selective, intensive, persistent, multifaceted, and participatory interventions.",

  "91578528", # Smith - The impact of the FRIENDS emotional health programme on anxiety, self-statements and coping strategies in children
  "The aim of this study was to evaluate the impact of the FRIENDS programme - a ten week cognitive behavioural intervention for anxiety in children - on anxiety, negative self-statements and coping strategies. The study took place in a large county within the south of England. Five schools agreed to participate in the study and parental and child consent was obtained for 83 participants. The children included in the study were aged between 9 and 10 years of age. The study utilised a quasi-experimental design incorporating an experimental and wait-list control group and pre- and post-test measures. The measures consisted of self-report questionnaires which were used to record changes in anxiety, use of negative self-statements and coping strategies. The findings showed the intervention was effective in increasing the use of approach coping strategies in children, although there was no significant reduction in avoidant coping strategies, as hypothesised. However, the expected reduction in anxiety was not evidenced. Furthermore, the intervention was found to significantly increase the self-reported use of negative self-statements. These findings are then discussed in relation to previous literature in the field and the implications for professional practice and recommendations for future research are then noted. It is concluded that, until the long term effects of this programme on negative self-statements and coping are known, the results from this study can not be used to support the recommended use of the FRIENDS programme in schools. Further research is therefore needed to ascertain the long term impact of the programme on negative self-statements and coping. Further research can also usefully investigate the relationships between negative self-statements and anxiety and also coping and anxiety.",

  "91578541", # Webster (2003) - An Ecological Approach to the Prevention of Anxiety Disorders during Childhood
  "Research shows that anxiety disorders are common and problematic in children. Treatment studies demonstrate that cognitive-behavioural interventions for children can successfully minimise these problems. Further, when implemented as early intervention or prevention programs, these interventions can prevent the onset of anxiety problems in 7 to 14 year olds and reduce existing levels of anxiety. This type of preventive approach has enormous potential for improving community mental health in a low cost model of service delivery. Yet, to develop this as a viable service model, these programs need to be evaluated under 'real world' conditions as opposed to specialist university clinical teams.\n\nIn this research, the long-term effectiveness of an ecological model of the prevention of anxiety disorders for children was conducted. In the first study, teachers (N = 17) were trained intensively in the principles of anxiety and the FRIENDS anxiety prevention program (Barrett, Lowry-Webster & Holmes, 1999). Measures were taken of the PROXIMAL effects of training on the knowledge and self-efficacy of participating teachers at two points in time. Compared to teachers in a control group (N= 17) and a group comprised of psychologists regarded as experts in the FRIENDS anxiety program (N= 22), trained teachers demonstrated significant increases in the levels of knowledge and self-efficacy at time two. These increases approached levels exhibited by experts in terms of knowledge, and were not significantly different from experts in their levels of self-efficacy to implement the FRIENDS program following training. This study also explored the quality or fidelity of program implementation by these trained teachers (INTERMEDIATE EFFECTS). Results demonstrated that trained teachers implemented the program with high levels of integrity in accordance with the FRIENDS intervention manual.\n\nThe second study sought to investigate the outcomes for participating children in terms of actually preventing and reducing existing levels of anxiety. Also of interest was the impact this intervention had on levels of depression. Participants were 594 children aged 10-13 years from 7 schools in Brisbane Australia. Children, and parents reported on children's social, emotional and behavioural characteristics at three-assessment points over 12 months. Results were examined universally (for all children) and for children who scored above the clinical cut-off for anxiety at pre-test. Results revealed that children in the FRIENDS intervention group reported fewer anxiety symptoms regardless of their risk status at posttest. In terms of reported levels of depression, only the high anxiety group who completed the FRIENDS intervention evidenced significant improvements at posttest. The results indicated that intervention gains were maintained over a period of 12 months, as measured by self-reports and diagnostic interviews. Moreover, evidence of a prevention effect was also demonstrated, with a significantly greater percentage of children in the control group progressed to 'at risk' or 'remained at risk' compared to children in the intervention group. Additionally, 85% of children in the intervention group who were scoring above the clinical cut-off for anxiety and depression were diagnosis free in the intervention condition at 12-month follow-up, compared to only 31.2% of children in the control group. Implications of these findings are examined, alongside limitations of the study and directions for future research.",

  "91578549", # Gökkaya - A School-Based Cognitive Behavioral Group Program for Anxious Youth
  "Untreated or undermined anxiety at elevated levels have a negative impact on youth's mental health, leading to various problems in the educational and psychosocial domain. School-based interventions play an important role in the prevention of anxiety disorders in children and adolescents. Accordingly, a group therapy program which includes cognitive behavioral therapy techniques was developed to reduce subclinical anxiety in school-aged children. This program is suitable for children aged 12 to 15 years and can be delivered in groups consisting of 6-8 children. The content of this program can be adapted for use in clinical settings but first it should be revised and tested for validity in clinical samples. The effectiveness of this program in the school environment was supported by an experimental study. Finally, it is necessary to have the basic knowledge about cognitive behavioral therapy techniques as well as training in childhood psychopathology in order to apply the prevention program presented in this book.",

  "91578559", # Kösters - IndicatedPreventionofChildhoodAnxietyand Depression:ResultsFromaPractice-BasedStudyupto 12MonthsAfterIntervention
  "Objectives. We investigated whether intervention effects of FRIENDS for Life, a school-based prevention program for children with anxiety or depression symptoms, were maintained over a period of 12 months after the intervention in a naturalistic setting. Methods. We used a quasi-experimental design, with 339 children in the intervention group and 157 in the control group (aged 8-13 years) in schools in Amsterdam, the Netherlands. We collected self-, teacher, and peer reports of anxiety and depression scores before and after intervention, and 6 and 12 months after intervention, from 2010 to 2012. Results. Intervention-group children reported a continuing and significant decrease in anxiety and depression scores compared with the control group. Twelve months after the intervention, participants' anxiety and depression levels were comparable to those of the general population. Girls reported a stronger decrease in anxiety scores than did boys. Teacher reports suggested no effects. Although classmates reported increased internalizing problems in intervention-group children immediately after intervention, these effects disappeared over time. Conclusions. FRIENDS for Life, an indicated prevention program, yielded long-lasting and continuing reduction in anxiety and depression problems when implemented in daily school practice.",

  "91578566", # Barker (2008) - Preventing anxiety disorders in youth : universal school-based intervention
  "Childhood anxiety disorders are highly prevalent, cause significant distress and functional impairment, are risk factors for depression, suicidal ideation and attempts, substance abuse and smoking, yet often go unrecognized and untreated. As a result, effective prevention and early intervention have become policy and research priorities. This study evaluated the effectiveness of a universal school-based cognitive behavioural intervention in decreasing anxiety symptoms experienced by early adolescents during the transition from elementary to middle or secondary school. The role of gender, coping style, geographic location, and timing of the intervention were also assessed. Participants were 722 grade 7 and 8 students (11-14 years) from 41 classrooms in 20 randomly selected public schools in British Columbia. Schools were randomly assigned to either the FRIENDS for Youth program provided within regular classrooms, one hour weekly for 10 weeks or to a waitlist control group. Self-reported anxiety, depression and coping, and parent and teacher assessed difficulties were assessed at pre-, post, and six month follow-up. Results were examined universally and for children who scored above the clinical cut-off for anxiety at pre-test. Results indicate students, including those 'at risk', who participated in the FRIENDS for Youth program had lower anxiety than those in the control group at 6-month follow-up. Gender differences in self-reported anxiety as well as in response to the intervention were found, with girls, including those 'at risk' reporting higher anxiety scores than boys, and intervention group girls reporting significantly lower anxiety scores at post-intervention and at 6-month follow-up compared to the control group. Teachers assessed girls as having lower difficulties scores than boys, and intervention group girls reporting significantly lower difficulties scores at post-intervention than the control group. Grade 7 elementary students had significantly lower anxiety scores than middle school students and grade 7 students in the intervention group had significantly lower anxiety scores at post-intervention than the control group. Overall, intervention effects on anxiety were small. For 'at risk' participants and for girls, however, the intervention was effective. Results demonstrated a prevention effect with significantly fewer 'at risk' students at 6-month follow-up in the intervention group than the control group.",

  "91578570", # Doyle - Child anxiety, resiliency, and the FRIENDS for Life program
  "Anxiety disorders are the most commonly diagnosed group of mental disorders in children (Kessler et al., 2012). Resiliency, defined as a child's ability to successfully overcome an adverse event (Newland, 2014) is believed to be comprised of protective factors such as self-esteem and positive coping strategies (Rutter, 1987). These protective factors are related to child anxiety in that their presence or absence may augment or hinder a child's resiliency towards anxiety-provoking events and situations (Lo Casico, Guzzo, & Pace, 2013; Thorne, Andrews, & Nordstokke, 2013). The FRIENDS for Life (FFL) program is a school-based anxiety prevention program which aims to decrease anxiety and increase resiliency in 8- to 11-year-old children (Barrett & Sonderegger, 2003). Previous studies have shown FFL to be an effective tool in decreasing anxiety and increasing resiliency; however, not all previous studies have utilized control or comparison groups (Brownlee et al., 2013; Neil & Christensen 2007; Stopa, Barrett, & Golingi, 2011). Moreover, existing FRIENDS literature has not previously considered the potential role of parent anxiety in child outcomes. The present study aimed to evaluate child anxiety, resiliency, and parent anxiety in relation to the FFL program while including a no-treatment control group. It was hypothesized that child anxiety would decrease and child resiliency would increase following FFL. Results obtained from a non-identified school-based sample were not entirely consistent with predictions, such that decreases in anxiety and increases in resiliency were observed in both the experimental and control groups.",

  "91578580", # Green - An evaluation of a FRIENDS for Life programme in a mainstream secondary school...
  "A CBT programme designed to be run in school and community settings. The programme has been introduced to schools within the local authority where the researcher is based via the local Targeted Mental Health in Schools (TAMHS) project. The programme is well reviewed and is recommended by the World Health Organisation for the treatment of anxiety disorders in children (World Health Organisation, 2004). Previous research has evaluated the programme when delivered in closely monitored situations with optimal implementation. The aim of this study is to evaluate the impact of FRIENDS for Life as implemented in a mainstream secondary school by school staff trained as part of the TAMHS initiative. This study makes an original contribution to the existing research base by evaluating the programme in a naturalistic, real world setting using an alternative methodology to the majority of published evaluations. Data regarding implementation of the programme was collected and analysed using activity theory. A single case experimental design was used to monitor the impact of the intervention on the emotional distress, anxiety levels and coping strategies of 5 secondary school participants (aged 11-13) who had been identified by school staff as appearing anxious. The findings suggest that participation in FRIENDS did not result in the hypothesised reductions in emotional distress, anxiety and negative coping skills or the hypothesised improvement in active coping skills. These results are discussed with regard to the finding that some aspects of the programme were not delivered. Analysis of the context using activity theory suggested that factors such as lack of time, space for delivery and experience and training impacted upon implementation. Methodological issues contributing to these findings are considered and implications for the local TAMHS project and for Educational Psychologists are discussed.",

  "91578583", # Iizuka (2014) - The <scp>FRIENDS</scp> Emotional Health Program for Minority Groups at Risk
  'BACKGROUND\nDespite the existence of evidence-based interventions for promoting mental health in children, the number of children at risk remains high. One of the reasons is that such interventions are not reaching specific groups at risk such as low socioeconomic status and ethnic minority groups. This study evaluated an adaptation of a school-based psychosocial program for nonreferred students aged 11 to 12 years attending a multicultural school from a low socioeconomic status area.\n\nMETHODS\nThe FRIENDS Program was adapted for a multicultural population. A quasi-experimental design was used, involving a pre/post-test, to evaluate the impact of the intervention on participants\' outcomes on the Strengths and Difficulties Questionnaire (SDQ). Participants were divided into 2 categories ("at risk"/"not at risk") based on their scores in the SDQ at pre-test. Post-test data were collected to evaluate the overall effectiveness and acceptability of the program.\n\nRESULTS\nAnalyses showed significant improvement for the group initially identified as "at risk," with 30% of the students being no longer at risk after the intervention. Most students rated the intervention as being highly acceptable and useful.\n\nCONCLUSIONS\nAdaptations to existing evidence-based programs for implementation with specific minority groups at risk represents a promising approach to promote emotional health in children.',

  "91578584", # Gallegos (2012) - FRIENDS for Life Program for Mexican Girls Living in an Orphanage
  "Anxiety and depression are common problems experienced by children and adolescents that, without an effective intervention, can lead to a series of negative consequences. The aim of this study was to evaluate the effectiveness the Spanish version of the FRIENDS for Life program (Barrett, 2008a, 2008b), a social and emotional skills program that uses cognitive-behavioural techniques for the prevention and early intervention of anxiety and depression. The program was implemented at the selective level of prevention with girls living at an orphanage in Mexico. Participants received the program for 10 consecutive weeks, and pretest and post-test measures were administered. Measures evaluated participants' anxiety and depressive symptoms and risk status, proactive coping skills, levels of self-concept, self-esteem, and optimism. Social validity was also assessed. Results showed positive changes particularly in optimism and self-concept. Particular items and subscales of the measures also reported statistically significant changes, such as a decrease in worry, physiological symptoms of anxiety, and negative mood, and an increase in self-esteem at home and with peers. Participants evaluated the program as enjoyable and useful. Implications of the findings and further research are discussed.",

  "91578594", # Sanagooe (2021) - The effect FRIENDS program on the anxiety of adolescent girls
  "Background\nAnxiety is one of the most common psychological problems among adolescents which have been almost considered by researchers. In this regard, the present study was conducted to examine the effect of the FRIENDS training program on the anxiety of female adolescent clients referred to Tolou-e-Now Health Counseling Center of Bam.\n\nMethods\nThis study was a randomized controlled trial. The statistical population included 65 people of female adolescents with anxiety disorder referred to Tolou-e-Now Health Counseling Center of Bam, who were studying in academic year 2018-2019. Among them 30 people whose total anxiety level were higher than intermediate, were selected through convenience sampling method and randomly assigned to control (n=15) and experimental (n=15) groups. The experimental group received the FRIENDS training program for 10 sessions during 2 months and the control group did not receive any intervention. Spielberger State-Trait Anxiety Inventory was used to collect data. The data were analyzed using analysis of covariance and SPSS software version 22.\n\nResults\nThe results of analyzing the data showed that FRIENDS program training had a statistically significant effect on reducing both obvious and hidden anxiety in female adolescents in experimental compare to control group. The rate of the effect of this training program was estimated 33.4% with statistic potent 92.4.\n\nConclusion\nFRIENDS training program could be considered as a protective intervention on reducing anxiety of adolescents.",

  "91578598", # Carlyle - With a little help from FUN FRIENDS young children can overcome anxiety.
  "This article highlights resilience as a key concept when working with young children to improve their emotional wellbeing and reduce anxieties.",

  "91578682", # Lock (2003) - A longitudinal study of developmental differences in universal preventive intervention for child anxiety
  "The present paper presents the results of a longitudinal study evaluating the effects of a universal school-based intervention for child anxiety at two developmental stages. The study involved a cohort of 733 children enrolled in grade 6 (n = 336, 45.6%) aged between 9 and 10 years, and grade 9 (n = 401, 54.4%) aged between 14 and 16 years. Participants were allocated to either a school-based cognitive-behavioural intervention or to a monitoring group, and completed standardised measures of anxiety, depression and coping style. Young people identified as 'at risk' of an anxiety disorder were assessed for a clinical diagnosis with a structured diagnostic interview. Findings showed universal intervention as potentially successful in reducing symptoms of anxiety and increasing coping skills in children. Primary school children reported the greatest changes in anxiety symptoms, suggesting earlier preventive intervention was potentially more advantageous than later intervention. Developmental differences in anxiety, depression and coping strategies are discussed in addition to the implications and limitations of this study and directions for future research.",

  "91578690", # Cooley (2004) - Feasibility of an anxiety preventive intervention for community violence exposed African-American children
  "Investigated the feasibility of using an anxiety preventive intervention efficacious with Australian children with inner-city African-Americans (aged 10-11) who experienced moderate anxiety problems and community violence exposure. Of 91 fifth-grade students, ten participated in the school-based selective preventive intervention that targeted anxiety disorders. In this pilot study, qualitative and quantitative analyses revealed significant decreases in general anxiety and manifestations of anxiety that were contextually relevant to the community violence exposed youth (i.e., physiological symptoms, worry regarding environmental pressures, and concentration difficulties). The discussion focuses on the modifications necessary to make the prevention program culturally and contextually appropriate for anxious inner-city African-American children.",

  "91578701", # Famil (2020) - The effect of "FRIENDS for Life" and "Coping Cat" programs for reduction of anxiety symptoms on male children
  "Background: Anxiety disorder is the most common type of psychiatric disorders in children. The aim of this study was to compare two anxiety-prevention programs including FRIENDS for Life (FFL) and Coping Cat (CC) for anxious male children. Methods: This quasi-experimental study was performed using pre-and post-tests with two experimental and control groups. The population of this study included primary schoolchildren in District 5 of Tehran in 2019. Totally, 45 students aged 8 years were selected from 5 schools by cluster random sampling and were randomly assigned into 3 groups of 15. The two experimental groups participated in the one-hour therapy sessions of FFL and CC programs on a weekly basis. The Spence Children's Anxiety Scale (SCAS, 1998) was used to collect research data. Data were analyzed using multiple analysis of covariance (MANCOVA) via SPSS 24. Results: The results showed that both FFL and CC programs were effective on preschool children's anxiety (F=16.46; P=0.001). However, this effectiveness was not found in control group. Moreover, by examining the pairwise comparison between the effectiveness of the FFL and CC programs, it was observed that the FFL was more effective than the CC for the anxiety of preschool children. The value of Eta coefficient indicated the effectiveness of FFL in all subscales. Conclusions: Anxiety-prevention programs including FFL and CC have been effective in reducing children's anxiety. Hence, the application of these two interventions in schools helps anxious children to gain a deeper understanding of their various emotions and feelings to reduce their anxiety.",

  "91578703", # Barrett (2005) - Developmental differences in universal preventive intervention for child anxiety
  "We compared the effects of a universal school-based preventive intervention for child anxiety at two developmental stages. Six hundred and ninety-two participants enrolled in either grade 6 (n = 293), children aged between 9 and 10 years, or grade 9 (n = 399), children aged between 14 and 16 years, were allocated to either a school-based cognitive-behavioural intervention or to a monitoring group. Participants completed the Spence Child Anxiety Scale and the Child Depression Inventory and were stratified into low-, moderate- and high-risk groups based on their anxiety scores at the start of the study. The effects of the prevention programme were evaluated at post- and 12-month follow-up intervals. Post-study results indicated significant reductions in anxiety (p < .001) and depression (p < .05) across high- and moderate-risk groups in both the intervention and monitoring conditions. This trend was evident at 12-month follow-up, however, reductions in anxiety were greater in the intervention condition (p < .05). At post assessment, grade 6 participants showed significant changes in anxiety compared with grade 9 participants (p < .001), although both primary and secondary school participants showed equal reductions in anxiety at 12-month follow-up. Overall, findings suggest that universal intervention is potentially successful in reducing anxiety symptoms in children. Primary school children reported the greatest changes in anxiety symptoms, suggesting that earlier preventive intervention is potentially more advantageous than later intervention in adolescence. The implications and limitations of this study and directions for future research are discussed.",

  "91578709", # Hunt (2009) - Randomized controlled trial of an early intervention programme for adolescent anxiety disorders
  "Objective: To assess the effectiveness of an indicated early intervention and prevention programme for anxiety disorders when conducted by school staff.\n\nMethod: A total of 260 students in their first year of high school with self-reported anxiety symptoms 1SD above the mean score of a normative sample were randomly allocated on the basis of their school to an intervention condition led by school staff or to a monitoring condition.\n\nResults: There was little difference between conditions at the 2 year and 4 year follow up on self-reported symptoms, and no difference on diagnosis or health-care use.\n\nConclusions: Outcomes associated with indicated prevention programmes led by school staff may not be as strong as those produced by specialist mental health staff. More work is needed to delineate models by which evidence-based treatments can be effectively used in schools.",

  "91578724", # Kavanagh (2014) - Effects of the FRIENDS for Life Program on Anxiety, School Functioning, and Social Functioning
  "The aim of the current pilot trial was to evaluate the effects of the group-based FRIENDS for Life (FFL) program on school and social functioning in children with elevated levels of anxiety. Participants were 15 children aged eight to 12 identified by their parents as experiencing elevated levels of anxiety. Children attended six two-hour sessions of the FFL program and completed measures of anxiety, school functioning, and social functioning at pre- and post-treatment. Results indicated nonsignificant reductions from pre- to post-treatment in both child- and parent-report anxiety with large and medium effect sizes, respectively. Working memory scores increased significantly and there was a trend toward a significant increase in academic performance; large within group effects were found for both increases. The increase in academic functioning scores was significant with a moderate effect size only for child-report scores. A significant improvement with a large effect size was found for child-report peer relations scores and significant decreases were found for parent-report asocial behaviour and relational aggression scores, both with moderate effect sizes. Overall, children in this study demonstrated improvements in anxiety, school functioning, and social functioning. While reduction in anxiety is the primary focus of the FFL program additional benefits include improvements in school and social functioning. Though results are encouraging it is important to note that this was an uncontrolled pilot study with a small sample size. Thus results should be interpreted with caution. Nevertheless, the generally positive findings of this trial suggest a larger controlled trial is warranted. If these findings are replicated in a larger trial, the FFL may be a cost-effective, easily implemented, and versatile anxiety prevention program that can help change the trajectory of anxious children's school and social functioning."
)

# Attach each found abstract to the matching eppi_id (only rows still missing an abstract),
# warning if an eppi_id isn't found in the data so mismatches aren't applied silently.
for (i in seq_len(nrow(found_abstracts))) {
  match_idx <- which(
    friends_data$eppi_id == found_abstracts$eppi_id[i] &
      friends_data$abstract == "No information" &
      friends_data$human_code == 1L
  )

  if (length(match_idx) != 1) {
    warning(sprintf(
      "Expected exactly one match for eppi_id '%s', found %d",
      found_abstracts$eppi_id[i], length(match_idx)
    ))
  } else {
    friends_data$abstract[match_idx] <- found_abstracts$abstract_text[i]
  }
}

# Studies that still have "No information" (no abstract could be found online) after the update.
still_missing <- friends_data |>
  filter(abstract == "No information" & human_code == 1L) |>
  select(author_short, title, eppi_id, included_final)
print(still_missing, n = nrow(still_missing))

attr(friends_data, "data_name") <- "friends_data"

saveRDS(friends_data, "friends/data/friends_FRIENDS_2_cleaned.rds")
